package br.com.folha.notes;
import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
/** A two-device transport test. This Documents shim exists only in this JVM test output. */
class Documents {static void atomic(File f,String s) throws Exception {f.getParentFile().mkdirs();Files.write(f.toPath(),s.getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
public class SyncTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static class Device implements DriveSync.Local {
  File root;Map<String,JSONObject> docs=new TreeMap<>();String open="";Device(File root){this.root=root;root.mkdirs();}
  public List<String> ids(){return new ArrayList<>(docs.keySet());}public JSONObject read(String id) throws Exception {return new JSONObject(docs.get(id).toString());}public File file(String id,String rel) throws Exception {if(!DriveSync.validId(id))throw new IOException("id");DriveSync.relative(rel);return new File(new File(root,id),rel);}public boolean exists(String id){return docs.containsKey(id);}public boolean opened(String id){return open.equals(id);}
  public boolean install(JSONObject d,File stage,String expected) throws Exception {String id=d.getString("id");if(opened(id))return false;if(expected==null&&exists(id)||expected!=null&&(!exists(id)||!DriveSync.fingerprint(read(id)).equals(expected)))return false;for(String n:DriveSync.assetNames(d)){File f=new File(stage,n),to=file(id,n);if(f.exists()){to.getParentFile().mkdirs();Files.copy(f.toPath(),to.toPath(),StandardCopyOption.REPLACE_EXISTING);}}docs.put(id,new JSONObject(d.toString()));return true;}
 }
 static class Memory implements DriveSync.Remote {List<JSONObject> list=new ArrayList<>();Map<String,byte[]> bytes=new HashMap<>();int blobs;public List<JSONObject> files() throws Exception {List<JSONObject> out=new ArrayList<>();for(JSONObject f:list)out.add(new JSONObject(f.toString()));return out;}public String upload(String name,File f,JSONObject p) throws Exception {String id=UUID.randomUUID().toString();bytes.put(id,Files.readAllBytes(f.toPath()));list.add(new JSONObject().put("id",id).put("appProperties",p));if(p.optString("kind").equals("blob"))blobs++;return id;}public void download(String id,File f,long limit) throws Exception {if(bytes.get(id).length>limit)throw new IOException("limit");Files.write(f.toPath(),bytes.get(id));}}
 static JSONObject fresh(String id) throws Exception {return new JSONObject().put("version",2).put("id",id).put("name","Português e matemática").put("folder","").put("paper","lines").put("revision",UUID.randomUUID().toString()).put("updated",123).put("lastPage",0).put("pdf",true).put("count",1).put("pages",new JSONObject()).put("bookmarks",new JSONArray());}
 public static void main(String[] args) throws Exception {if(args[0].equals("--import-wire")){File source=new File(args[1]);Memory m=new Memory();JSONArray list=new JSONObject(DriveSync.readText(new File(source,"index.json"))).getJSONArray("files");for(int i=0;i<list.length();i++){JSONObject f=list.getJSONObject(i);String fid=f.getString("id");m.list.add(f);m.bytes.put(fid,Files.readAllBytes(new File(source,fid).toPath()));}File target=new File(args[2]);Device tablet=new Device(new File(target,"tablet"));new DriveSync(tablet,m,new File(target,"state"),"interop-account").run();JSONObject d=tablet.read("12345678-1234-1234-1234-123456789abc");check(d.getString("folder").equals("Windows roundtrip"),"Windows metadata not received");JSONArray points=d.getJSONObject("pages").getJSONArray("0").getJSONObject(0).getJSONArray("points");check(points.length()==2&&points.getJSONArray(0).getDouble(2)==.25&&points.getJSONArray(1).getDouble(2)==1.2,"Windows ink pressure/geometry lost");System.out.println("PASS Java -> Windows -> Java sync with editable pressure ink and original PDF");return;}File root=new File(args[0]);root.mkdirs();Device a=new Device(new File(root,"a")),b=new Device(new File(root,"b"));Memory remote=new Memory();String id="12345678-1234-1234-1234-123456789abc";JSONObject d=fresh(id);a.docs.put(id,d);File pdf=a.file(id,"source.pdf");pdf.getParentFile().mkdirs();Files.write(pdf.toPath(),"%PDF-test".getBytes());new DriveSync(a,remote,new File(root,"sa"),"same-account").run();new DriveSync(b,remote,new File(root,"sb"),"same-account").run();check(b.read(id).getString("name").equals(d.getString("name")),"initial download");check(remote.blobs==1,"PDF dedup");System.out.println("PASS transfer and PDF deduplication");
 a.docs.get(id).put("name","Edição do tablet");b.docs.get(id).put("folder","Edição do PC");new DriveSync(a,remote,new File(root,"sa"),"same-account").run();new DriveSync(b,remote,new File(root,"sb"),"same-account").run();new DriveSync(a,remote,new File(root,"sa"),"same-account").run();check(a.docs.size()==2,"conflict count");check(a.docs.values().stream().anyMatch(v->v.optString("name").startsWith("Edição do tablet")),"tablet edit lost");check(a.docs.values().stream().anyMatch(v->v.optString("folder").equals("Edição do PC")),"PC edit lost");check(remote.blobs==1,"PDF reuploaded");System.out.println("PASS concurrent edits preserved");int n=remote.list.size();new DriveSync(a,remote,new File(root,"sa"),"same-account").run();new DriveSync(b,remote,new File(root,"sb"),"same-account").run();check(remote.list.size()==n,"not idempotent");System.out.println("PASS idempotent sync");
 a.docs.get(id).put("name","Nova edição");new DriveSync(a,remote,new File(root,"sa"),"same-account").run();b.open=id;String old=b.read(id).optString("name");new DriveSync(b,remote,new File(root,"sb"),"same-account").run();check(b.read(id).optString("name").equals(old),"open overwritten");b.open="";new DriveSync(b,remote,new File(root,"sb"),"same-account").run();check(b.read(id).optString("name").equals("Nova edição"),"closed did not update");System.out.println("PASS open document protection");
 check(DriveSync.conflictId(id,"00000000-1111-2222-3333-444444444444").equals(args[1]),"cross-platform conflict identifier");boolean rejected=false;try{DriveSync.relative("../account.bin");}catch(Exception e){rejected=true;}check(rejected,"traversal");System.out.println("PASS portable identifier and path validation");
 // Export the real wire representation, allowing the Windows test suite to import it.
 File wire=new File(root,"wire");wire.mkdirs();JSONArray index=new JSONArray();for(JSONObject f:remote.list){String fid=f.getString("id");Files.write(new File(wire,fid).toPath(),remote.bytes.get(fid));index.put(f);}Files.write(new File(wire,"index.json").toPath(),new JSONObject().put("files",index).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));
 }
}
